import{_ as t,o,c as a,a2 as i}from"./chunks/framework.BV2xZELn.js";const h=JSON.parse('{"title":"Sweet-Melon — Audit Execution Plan","description":"","frontmatter":{},"headers":[],"relativePath":"AUDIT_EXECUTION_PLAN.md","filePath":"AUDIT_EXECUTION_PLAN.md","lastUpdated":1791852188000}'),d={name:"AUDIT_EXECUTION_PLAN.md"};function n(s,e,r,c,l,u){return o(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="sweet-melon-—-audit-execution-plan" tabindex="-1">Sweet-Melon — Audit Execution Plan <a class="header-anchor" href="#sweet-melon-—-audit-execution-plan" aria-label="Permalink to &quot;Sweet-Melon — Audit Execution Plan&quot;">​</a></h1><p>Status legend: <code>[ ]</code> Not Started · <code>[~]</code> In Progress · <code>[x]</code> Completed · <code>[-]</code> Not Applicable · <code>[!]</code> Blocked (only for real external constraints).</p><p>Convention for <code>[-]</code>: reserved for an item that does not apply to this repository, with the reason written next to it. It is never used for unfinished, deferred or unverified work. No item in this plan uses <code>[-]</code>.</p><p>Definition of Done for a finding: problem identified, root cause identified, implementation fixed, tests added and passing, regression protected, documentation updated, plan updated, worklog updated.</p><hr><h2 id="_1-executive-summary" tabindex="-1">1. Executive Summary <a class="header-anchor" href="#_1-executive-summary" aria-label="Permalink to &quot;1. Executive Summary&quot;">​</a></h2><p>Sweet-Melon is a Flutter application that exposes Android/iOS native capabilities (camera, storage, geolocation) to JavaScript running inside a <code>webview_flutter</code> WebView through a message bridge.</p><p>The initial audit found that the repository was a prototype: no tests, no CI, no <code>.gitignore</code>, and several security and correctness gaps on the most sensitive path (JavaScript → native). The most serious issues were:</p><ul><li>the native bridge was reachable from every frame and from any navigated origin (SEC-001);</li><li>a path traversal in the storage plugin (<code>listFiles</code>) (SEC-002);</li><li>cached write operations returning stale or skipped writes (BUG-001);</li><li>permissions implicitly granted and capabilities that were only metadata (SEC-005, ARCH-002).</li></ul><p>This pass fixes the P0/P1 items, adds unit, integration, security, regression, JavaScript-SDK and (on Android) end-to-end tests, adds a CI workflow, and documents the real behaviour. Items that cannot be verified from this sandbox would be recorded as <code>[!]</code> with the concrete reason in section 15. None remain.</p><h2 id="_2-repository-overview" tabindex="-1">2. Repository Overview <a class="header-anchor" href="#_2-repository-overview" aria-label="Permalink to &quot;2. Repository Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>lib/main.dart</code>, <code>lib/app.dart</code></td><td>Application entry point</td></tr><tr><td><code>lib/di/service_locator.dart</code></td><td>Composition root (get_it)</td></tr><tr><td><code>lib/screens/home_screen.dart</code></td><td>Demo screen + demo JavaScript page</td></tr><tr><td><code>lib/packages/core</code></td><td>Protocol, bridge, WebView host, logger</td></tr><tr><td><code>lib/packages/plugin_engine</code></td><td>Plugin contract, registry, manager pipeline</td></tr><tr><td><code>lib/packages/security</code></td><td>Execution guard, rate limiter, permissions, sandbox path</td></tr><tr><td><code>lib/packages/performance</code></td><td>LRU/TTL cache</td></tr><tr><td><code>lib/packages/devtools</code></td><td>Bridge inspector (debug only)</td></tr><tr><td><code>lib/plugins/{camera,storage,geolocation}</code></td><td>Native plugins</td></tr><tr><td><code>android/</code>, <code>ios/</code>, <code>web/</code></td><td>Platform projects (web is the Flutter default and is not a bridge target)</td></tr><tr><td><code>test/</code></td><td>Unit, integration, security, regression tests (Dart) and <code>test/js</code> (SDK)</td></tr><tr><td><code>integration_test/</code></td><td>End-to-end test on a real Android WebView</td></tr><tr><td><code>docs/</code></td><td>Plan, worklog, architecture, security, testing docs</td></tr></tbody></table><p>Layout note (ARCH-001): the in-tree &quot;packages&quot; are not separate pub packages. Their unused nested <code>pubspec.yaml</code> files were removed; everything is one package <code>sweetmelon</code> and is imported as <code>package:sweetmelon/packages/...</code>.</p><h2 id="_3-architecture-overview" tabindex="-1">3. Architecture Overview <a class="header-anchor" href="#_3-architecture-overview" aria-label="Permalink to &quot;3. Architecture Overview&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>JavaScript (page)            window.Native.call / batch / on</span></span>
<span class="line"><span>    │  JSON string, token     flutterBridge.postMessage</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>WebViewHost (runtime)        channel → size limit → NavigationPolicy (for loads)</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>MessageBridge (core)         session token check → protocol parse → dispatch</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>PluginManager (engine)       resolve → method/capability → rate limit →</span></span>
<span class="line"><span>    │                        permission → validate args → cache → concurrency</span></span>
<span class="line"><span>    │                        → ExecutionGuard (timeout) → plugin.onCall</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>Plugin (camera/storage/geo)  SandboxPath · PlatformPermission · platform APIs</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>Native Android/iOS APIs</span></span>
<span class="line"><span>    ▲</span></span>
<span class="line"><span>PluginResponse / Event       window.__resolveCall / __resolveBatch / __emitEvent</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>JavaScript                   promise settled / listener invoked</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><p>See <code>docs/ARCHITECTURE.md</code> for the full description.</p><h2 id="_4-current-state-before-this-pass" tabindex="-1">4. Current State (before this pass) <a class="header-anchor" href="#_4-current-state-before-this-pass" aria-label="Permalink to &quot;4. Current State (before this pass)&quot;">​</a></h2><ul><li>Dart: ~4.4k lines, 0 tests, analyzer never run in repo.</li><li>Android: builds configured, release signed with debug key, duplicate MainActivity.</li><li>iOS: project present; no Podfile in repository; no usage descriptions.</li><li>CI: none. Documentation: README empty.</li></ul><h2 id="_5-findings" tabindex="-1">5. Findings <a class="header-anchor" href="#_5-findings" aria-label="Permalink to &quot;5. Findings&quot;">​</a></h2><p>Priority: P0 critical · P1 high · P2 medium · P3 low · P4 improvement.</p><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h3><ul><li>[x] <strong>SEC-001 (P0)</strong> JavaScript trust boundary. The <code>flutterBridge</code> channel was exposed to all frames; any page could post requests; navigation to any origin was allowed when <code>allowedHosts</code> was empty; non-HTTP schemes were not filtered. Fix: <code>NavigationPolicy</code> (default deny remote, block non-http(s) schemes), SDK installed only in the top frame, per-session random token that every message must carry (constant-time compare), tokens invalidated on every page start.</li><li>[x] <strong>SEC-002 (P0)</strong> Storage path traversal. <code>listFiles</code> skipped <code>..</code> validation and only compared strings; no symlink containment anywhere. Fix: <code>SandboxPath</code> validates syntax (no absolute, no <code>..</code>, no NUL/backslash/colon), canonicalises the nearest existing ancestor and rejects symlinks.</li><li>[x] <strong>SEC-003 (P1)</strong> Error disclosure. Responses contained <code>stackTrace</code> and raw <code>e.toString()</code> messages. Fix: unexpected exceptions return a generic message (<code>Internal error</code> in the bridge, <code>Plugin execution failed</code> in the manager; see 5b); stack traces are logged natively only.</li><li>[x] <strong>SEC-004 (P1)</strong> No message size limit and no request-origin check on bridge input. Fix: 2 MiB limit, token check, strict protocol validation.</li><li>[x] <strong>SEC-005 (P1)</strong> Implicit permission grants (<code>StaticPermissionProvider</code> granted camera/storage/location always) and permission cache that never expires. Fix: <code>PlatformPermissionProvider</code> (permission_handler + sandbox rules), 5 s TTL cache, explicit <code>permanentlyDenied</code> status returned to JS.</li><li>[x] <strong>SEC-006 (P1)</strong> Android release build signed with the debug key. Fix: release signing read from environment; without it release is unsigned.</li><li>[x] <strong>SEC-007 (P2)</strong> Debug inspector (shows every bridge payload) was shown in production. Fix: FAB and inspector only in debug builds (<code>kDebugMode</code>; see 5b).</li><li>[x] <strong>SEC-008 (P2)</strong> Rate-limiter buckets keyed by untrusted names (unbounded growth). Fix: buckets only for registered plugin methods; idle buckets are pruned.</li><li>[x] <strong>SEC-009 (P2)</strong> Unbounded storage read/write size. Fix: 5 MiB file limit.</li><li>[x] <strong>SEC-010 (P3)</strong> Camera returns absolute temporary file paths to JS. Accepted and documented (needed for picker results); see <code>docs/SECURITY.md</code>.</li></ul><h3 id="bugs" tabindex="-1">Bugs <a class="header-anchor" href="#bugs" aria-label="Permalink to &quot;Bugs&quot;">​</a></h3><ul><li>[x] <strong>BUG-001 (P0)</strong> Storage cache: <code>set</code>, <code>remove</code>, <code>writeFile</code>, <code>deleteFile</code> were cacheable (a second identical write was served from cache and never executed) and no mutation invalidated reads (stale data). Fix: read-only method declaration, invalidation of the plugin&#39;s cached reads on every successful mutation (key-prefix invalidation; see 5b).</li><li>[x] <strong>BUG-002 (P1)</strong> Batch: an exception or malformed batch never resolved the JS promise; <code>options.timeout</code> ignored in JS. Fix: batch envelope validation, batch error response, per-item timeout, JS-side batch timeout.</li><li>[x] <strong>BUG-003 (P1)</strong> Bridge <code>_isReady</code> was never reset on reload/navigation; responses for the previous page were sent into the new page; the pending script queue was unbounded. Fix: sessions (<code>startSession</code>/<code>endSession</code>), stale-session responses dropped, bounded queue.</li><li>[x] <strong>BUG-004 (P1)</strong> <code>emitEvent</code> with a primitive payload produced invalid JS for the SDK (<code>JSON.parse</code> of a non-string); non-serialisable payloads threw. Fix: payload double-encoded; serialisation errors are logged and dropped.</li><li>[x] <strong>BUG-005 (P1)</strong> Geolocation <code>watchPosition</code> discarded every position; only one watch; no event delivery. Fix: <code>watchId</code>-based watches, <code>geolocation.position</code> and <code>geolocation.error</code> events, <code>clearWatch({watchId})</code>, dispose cancels all.</li><li>[x] <strong>BUG-006 (P2)</strong> Malformed requests: <code>json[&#39;requestId&#39;] as String? ?? &#39;unknown&#39;</code> could throw inside the error handler and answered a non-existent id. Fix: protocol validation with typed <code>ProtocolException</code>.</li><li>[x] <strong>BUG-007 (P2)</strong> <code>stopOnError</code> ignored in parallel batches; missing results possible. Fix: every request gets a result; sequential stop emits <code>CANCELLED</code> for skipped items; documented limitation for parallel dispatch. Evidence: <code>test/regression/batch_stop_on_error_test.dart</code> (sequential CANCELLED, parallel limitation, timed-out batch dispatches nothing later), passed in CI run 37835701145 (commit <code>8b1fa1a</code>).</li><li>[x] <strong>BUG-008 (P1)</strong> User cancellation of camera reported as <code>EXECUTION_ERROR</code>. Fix: <code>CANCELLED</code> error code. Decision: a user cancel is counted in <code>errorCount</code> (it produced no result), with code <code>CANCELLED</code>. Evidence: <code>test/regression/camera_cancel_test.dart</code>, passed in CI run 37835701145.</li><li>[x] <strong>BUG-009 (P1)</strong> Argument casts in plugins threw <code>TypeError</code> and surfaced as <code>EXECUTION_ERROR</code>. Fix: validation before execution, <code>INVALID_ARGS</code> mapping.</li><li>[x] <strong>BUG-010 (P1)</strong> Android manifest lacked CAMERA and location permissions; iOS lacked usage descriptions (plugins would fail or crash at runtime). Fix: manifest permissions and Info.plist usage strings.</li><li>[x] <strong>BUG-011 (P2)</strong> WebView host never detached its controller from the bridge on dispose. Fix: detach + end session in <code>dispose()</code>, through <code>BridgeAttachment</code>, so a late callback of a superseded host cannot change the live session. Evidence: <code>test/regression/webview_lifecycle_test.dart</code>, passed in CI run 37835701145.</li><li>[x] <strong>BUG-012 (P1)</strong> Rate limiter used <code>num.clamp</code> where an <code>int</code> is required (type error risk). Fix: explicit integer arithmetic.</li><li>[x] <strong>BUG-013 (P2)</strong> <code>watchPosition</code> / <code>getCurrentPosition</code> had no timeout argument. Fix: <code>timeoutMs</code> (1..60000) mapped to the location time limit.</li></ul><h3 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h3><ul><li>[x] <strong>ARCH-001 (P2)</strong> Unused nested <code>pubspec.yaml</code> files in <code>lib/packages/*</code> and <code>lib/plugins/*</code> (not wired into the build). Fix: removed; single package.</li><li>[x] <strong>ARCH-002 (P1)</strong> Capability metadata (<code>supportsStreaming</code>, <code>supportsCache</code>, <code>maxConcurrentCalls</code>, <code>supportsBatch</code>) and the separate <code>cacheable</code> flag disagreed and were not enforced. Fix: <code>PluginCapabilities</code> is the single source; the manager enforces streaming, cache and concurrency.</li><li>[x] <strong>ARCH-003 (P2)</strong> Dead code: <code>ArgsValidator</code>/<code>ArgSchema</code>, <code>MemorySink</code>, <code>FileSink</code> (stub that never wrote), <code>PluginManifest</code>, <code>PermissionPolicy</code>, <code>checkPlugin</code>, <code>BatchRequest</code>, <code>PluginRequest.create</code>, <code>recordError</code>, unused cache patterns, lifecycle hooks <code>onPause</code>/<code>onResume</code>, unused <code>http</code>/<code>uuid</code> dependencies, unused <code>allowFileAccess</code>/<code>defaultTimeoutMs</code> configuration. Fix: removed or wired.</li><li>[x] <strong>ARCH-004 (P2)</strong> The bridge depended on <code>webview_flutter</code>. Fix: <code>JsExecutor</code> abstraction; only <code>WebViewHost</code> touches the WebView.</li><li>[x] <strong>ARCH-005 (P3)</strong> Duplicate <code>MainActivity</code> in <code>com/example/sweetmelon</code> (not referenced by the manifest). Fix: removed.</li><li>[x] <strong>ARCH-006 (P2)</strong> Two validation result types (<code>ValidationResult</code>, <code>ArgsValidationResult</code>). Fix: one type with optional error code.</li><li>[x] <strong>ARCH-007 (P3)</strong> Hard-coded 30 s timeout in the manager ignored the guard configuration. Fix: the guard&#39;s default is used.</li></ul><h3 id="statistics-metrics" tabindex="-1">Statistics / Metrics <a class="header-anchor" href="#statistics-metrics" aria-label="Permalink to &quot;Statistics / Metrics&quot;">​</a></h3><ul><li>[x] <strong>STAT-001 (P1)</strong> <code>errorCount</code> was never incremented and error paths (validation, permission, rate limit, timeout, exceptions) were not recorded. Fix: each call&#39;s outcome is recorded once in <code>totalCalls</code>; failures are also counted in <code>errorCount</code>; <code>activeCalls</code> returns to 0 when idle.</li></ul><h3 id="concurrency" tabindex="-1">Concurrency <a class="header-anchor" href="#concurrency" aria-label="Permalink to &quot;Concurrency&quot;">​</a></h3><ul><li>[x] <strong>CONC-001 (P1)</strong> <code>maxConcurrentCalls</code> not enforced. Fix: an in-flight counter per plugin in <code>PluginManager</code>; excess calls fail fast with <code>RATE_LIMIT_EXCEEDED</code> (retryable). Camera uses 1 because the image picker rejects concurrent presentations.</li><li>[x] <strong>CONC-002 (P2)</strong> Execution guard counted duplicate request ids incorrectly. Fix: reference-counted in-flight map.</li></ul><h3 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h3><ul><li>[x] <strong>PERM-001 (P1)</strong> Permission denial now includes <code>status</code> (<code>denied</code> / <code>permanentlyDenied</code> / <code>unsupported</code>, the <code>PermissionState</code> values) in error details so the JS side can prompt for settings. The check runs on every call for each permission the plugin declares.</li></ul><h3 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h3><ul><li>[x] <strong>PERF-001 (P2)</strong> LRU eviction was O(n) on each insert and overwrites evicted an unrelated entry. Fix: <code>LinkedHashMap</code> based O(1) LRU; overwrites do not evict.</li><li>[x] <strong>PERF-002 (P3)</strong> Gradle heap of 8 GiB (<code>-Xmx8G</code>) would fail on hosted runners. Fix: reduced to 3 GiB (<code>-Xmx3G</code>; see 5b for the values tried).</li></ul><h3 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h3><ul><li>[x] <strong>TEST-001 (P0)</strong> No tests existed. Fix: unit, integration, security, regression, performance-smoke and JavaScript-SDK tests (<code>test/</code>, <code>test/js/</code>).</li><li>[x] <strong>TEST-002 (P1)</strong> No coverage measurement. Fix: <code>flutter test --coverage</code> with a line-coverage gate (<code>.github/scripts/coverage_gate.py</code>, 55 %).</li><li>[x] <strong>TEST-003 (P2)</strong> No device-level E2E. Fix: <code>integration_test/app_test.dart</code> (the planned file name was changed; see 5b) run on an Android emulator in CI. It covers boot and the storage path through the engine, not JS inside the WebView.</li></ul><h3 id="ci" tabindex="-1">CI <a class="header-anchor" href="#ci" aria-label="Permalink to &quot;CI&quot;">​</a></h3><ul><li>[x] <strong>CI-001 (P0)</strong> No CI. Fix: <code>.github/workflows/ci.yml</code> (format, analyze, unit/integration/security tests, JS SDK tests, coverage gate, Android debug build, Android emulator E2E).</li><li>[x] <strong>CI-002 (P2)</strong> No <code>.gitignore</code>: <code>.dart_tool</code>, <code>build</code>, <code>local.properties</code>, keystores and IDE files were committable. Fix: Flutter-appropriate <code>.gitignore</code>.</li></ul><h3 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><ul><li>[x] <strong>DOC-001 (P2)</strong> README was empty. Fix: README with setup, commands and layout.</li><li>[x] <strong>DOC-002 (P2)</strong> No architecture, security or testing documentation. Fix: <code>docs/ARCHITECTURE.md</code>, <code>docs/SECURITY.md</code>, <code>docs/TESTING.md</code>.</li><li>[x] <strong>DOC-003 (P3)</strong> Stale comments/strings (<code>Hello World</code> display name, placeholder RunnerTests). Fix: corrected.</li></ul><h3 id="known-platform-gap" tabindex="-1">Known platform gap <a class="header-anchor" href="#known-platform-gap" aria-label="Permalink to &quot;Known platform gap&quot;">​</a></h3><ul><li>[x] <strong>IOS-001 (P2)</strong> The iOS project had no <code>ios/Podfile</code> and was never built. Resolved: <code>ios/Podfile</code> is committed with the <code>permission_handler</code> macros, the deployment target is 13.0, and an iOS job in CI builds the app on macOS with <code>flutter build ios --debug --no-codesign</code>. Running on a device is not covered.</li></ul><h2 id="_5a-known-finding-mapping-sm-001-sm-012" tabindex="-1">5a. Known-finding mapping (SM-001 … SM-012) <a class="header-anchor" href="#_5a-known-finding-mapping-sm-001-sm-012" aria-label="Permalink to &quot;5a. Known-finding mapping (SM-001 … SM-012)&quot;">​</a></h2><p>The user-supplied findings are mapped to the plan IDs below. Each row names the fix and the test that protects it.</p><table tabindex="0"><thead><tr><th>SM</th><th>Finding</th><th>Plan ID(s)</th><th>Fix</th><th>Protecting test</th></tr></thead><tbody><tr><td>SM-001</td><td>JS trust boundary / unrestricted JS</td><td>SEC-001, SEC-004, ARCH-004</td><td>navigation policy, top-frame SDK, per-session token, JsExecutor</td><td><code>navigation_policy_test</code>, <code>message_bridge_test</code> (token), <code>bridge_sdk.test.mjs</code></td></tr><tr><td>SM-002</td><td>Capabilities not enforced</td><td>ARCH-002, CONC-001</td><td>streaming / batch / cache / concurrency enforced in manager</td><td><code>plugin_manager_test</code> (streaming, batch, maxConcurrentCalls)</td></tr><tr><td>SM-003</td><td>Storage writes cacheable, no invalidation</td><td>BUG-001</td><td>cacheable methods are read-only; writes invalidate</td><td><code>plugin_manager_test</code> regression: write executes, write invalidates</td></tr><tr><td>SM-004</td><td>Guard timeout hard-coded, no concurrency enforcement</td><td>ARCH-007, CONC-001, CONC-002</td><td>timeout from <code>PluginManagerConfig</code>; per-plugin in-flight limit; duplicate-id rejection</td><td><code>plugin_manager_test</code> (timeout from config, concurrency, duplicate)</td></tr><tr><td>SM-005</td><td><code>errorCount</code> never incremented; error paths unrecorded</td><td>STAT-001</td><td>every failure path records stats and a trace</td><td><code>plugin_manager_test</code> (errorCount on each failure path, traces)</td></tr><tr><td>SM-006</td><td>Bridge lifecycle: stale state across reloads</td><td>BUG-003, BUG-011</td><td>sessions; stale responses dropped; dispose ends session</td><td><code>message_bridge_test</code> regression: stale-session response dropped</td></tr><tr><td>SM-007</td><td>Pending request cleanup</td><td>BUG-003, CONC-002, BUG-011</td><td>in-flight entries removed in <code>finally</code>; <code>cancelAll</code> on dispose; batch settles</td><td><code>security_units_test</code> (guard), <code>plugin_manager_test</code> (dispose cancels)</td></tr><tr><td>SM-008</td><td>Batch lifecycle (unsettled batches)</td><td>BUG-002, BUG-007</td><td>per-item results always present; batch timeout; stopOnError semantics</td><td><code>plugin_manager_test</code> batch group, <code>bridge_sdk.test.mjs</code> batch timeout</td></tr><tr><td>SM-009</td><td>Geolocation watch discards positions</td><td>BUG-005</td><td><code>watchId</code> streams delivering <code>geolocation.position</code>; max 4; cleanup</td><td><code>geolocation_lifecycle_test</code> (watch IDs, stream error removes watch, watch limit); the native position stream is not device-tested (TEST-003)</td></tr><tr><td>SM-010</td><td>Error contract leaks internals</td><td>SEC-003</td><td>generic message to JS; details logged natively</td><td><code>plugin_manager_test</code> error-contract group</td></tr><tr><td>SM-011</td><td>Geolocation stream lifecycle</td><td>BUG-005 (cleanup)</td><td>subscriptions removed on cancel, end, error and dispose</td><td><code>geolocation_lifecycle_test</code> (<code>clearWatch</code> cancels, dispose cancels all); the platform subscription is not device-tested</td></tr><tr><td>SM-012</td><td>Resource disposal</td><td>BUG-011, BUG-005, BUG-003</td><td><code>WebViewHost.dispose</code> detaches; bridge/manager/registry dispose</td><td><code>message_bridge_test</code> (dispose), <code>plugin_manager_test</code> (dispose)</td></tr></tbody></table><p>SM-007 and SM-011 are covered at the Dart level only. The native side (the real geolocation subscription and the picker) is not exercised on a device; see <code>docs/TESTING.md</code>, &quot;What is not covered&quot;.</p><h2 id="_5b-deviations-from-the-original-plan" tabindex="-1">5b. Deviations from the original plan <a class="header-anchor" href="#_5b-deviations-from-the-original-plan" aria-label="Permalink to &quot;5b. Deviations from the original plan&quot;">​</a></h2><p>Each deviation is a decision made during implementation. The reason is recorded in <code>docs/WORKLOG.md</code>.</p><ul><li><strong>SEC-003 message.</strong> The plan text says <code>Internal error</code>. The bridge still sends <code>Internal error</code> for its own failures. The plugin manager sends <code>Plugin execution failed</code> for exceptions thrown by plugins, which says which step failed without naming internals. Both are generic.</li><li><strong>SEC-005 TTL.</strong> Set to 5 s as planned. The manager reports <code>status</code> in details; <code>restricted</code> and <code>notDetermined</code> from the plan are reported as <code>denied</code> because <code>permission_handler</code> does not expose them on every platform.</li><li><strong>SEC-007.</strong> The inspector is gated by <code>kDebugMode</code> (not by the <code>enableDebugging</code> config) so that release builds cannot show it even with a misconfigured host.</li><li><strong>BUG-001 invalidation.</strong> Cache keys are not generation-based. A successful non-cacheable call invalidates the plugin&#39;s cache by key prefix. This is simpler and has the same observable effect. The BUG-001 <code>Fix</code> line above says the same.</li><li><strong>BUG-007.</strong> Parallel batches run concurrently; <code>stopOnError</code> is applied only to sequential batches. Documented in <code>docs/SECURITY.md</code>.</li><li><strong>BUG-012.</strong> The limiter uses integer arithmetic on milliseconds; no <code>clamp</code>.</li><li><strong>PERF-002.</strong> Heap reduced from 8 GiB to 3 GiB (<code>org.gradle.jvmargs=-Xmx3G</code>). The plan suggested 4 GiB; 4 GiB and then 2 GiB were tried. 2 GiB failed in <code>JetifyTransform</code> with <code>Java heap space</code>. Jetifier is also disabled (<code>android.enableJetifier=false</code>): every plugin here is AndroidX, and the transform was the main memory consumer. Kotlin daemon heap is 1.5 GiB.</li><li><strong>Toolchain minimums (CI-001).</strong> Flutter&#39;s current minimums are Gradle 8.14, AGP 8.11.1 and Kotlin 2.2.20. The repo was on Gradle 8.10.2, AGP 8.7.0 and Kotlin 1.8.22 and failed the debug build. The versions were raised to the minimums.</li><li><strong>Folders.</strong> Tests live in <code>test/unit/</code>, <code>test/security/</code>, <code>test/regression/</code>, <code>test/integration/</code>, <code>test/performance/</code> and <code>test/js/</code>, as in 9.</li><li><strong>Format and analyzer gate.</strong> The plan asked for <code>dart format --set-exit-if-changed</code> and <code>flutter analyze --fatal-infos</code>. CI runs <code>flutter analyze --fatal-warnings</code>. The format check runs in CI through <code>.github/scripts/format_report.sh</code>, which also publishes the diff of any unformatted file as a check run.</li><li><strong>Coverage gate.</strong> Coverage is generated, uploaded, and enforced at 55 % by <code>.github/scripts/coverage_gate.py</code> in CI (TEST-002).</li><li><strong>E2E.</strong> <code>integration_test/app_test.dart</code> replaces the planned <code>app_e2e_test.dart</code> (TEST-003). It covers boot, the WebView host and the storage path through the engine. It does not drive JavaScript through the WebView (TEST-003).</li></ul><h2 id="_6-risks" tabindex="-1">6. Risks <a class="header-anchor" href="#_6-risks" aria-label="Permalink to &quot;6. Risks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Risk</th><th>Mitigation</th></tr></thead><tbody><tr><td>Dart code could not be compiled inside the sandbox</td><td>Every change is verified by CI; failures are fixed and re-pushed (section 14)</td></tr><tr><td><code>permission_handler</code> on iOS needs Podfile macros</td><td><code>ios_permissions.py</code> checks the Podfile in CI; the iOS job builds the app without codesign (IOS-001). The app is not run on an iOS device.</td></tr><tr><td>Parallel batch cannot cancel already dispatched calls</td><td>Documented limitation; sequential mode honours <code>stopOnError</code></td></tr><tr><td>Dart futures cannot be cancelled after timeout</td><td>Guard reports <code>TIMEOUT</code>; underlying plugin work may finish later (documented)</td></tr><tr><td>WebView iframes can still call the raw channel</td><td>Token prevents use; documented in SECURITY.md</td></tr></tbody></table><h2 id="_7-priorities" tabindex="-1">7. Priorities <a class="header-anchor" href="#_7-priorities" aria-label="Permalink to &quot;7. Priorities&quot;">​</a></h2><ol><li>P0: SEC-001, SEC-002, BUG-001, TEST-001, CI-001.</li><li>P1: SEC-003/004/005/006, BUG-002/003/004/005/008/009/010/012, STAT-001, CONC-001, PERM-001, ARCH-002, TEST-002, TEST-003.</li><li>P2/P3: remaining items.</li></ol><p>Technical dependency order: protocol and sandbox before plugins; capabilities before concurrency and cache; tests alongside each change; CI last, then verified by GitHub Actions.</p><h2 id="_8-implementation-plan" tabindex="-1">8. Implementation Plan <a class="header-anchor" href="#_8-implementation-plan" aria-label="Permalink to &quot;8. Implementation Plan&quot;">​</a></h2><ul><li>[x] 8.1 Baseline and plan/worklog files</li><li>[x] 8.2 Remove dead code and unwired packages (ARCH-001, ARCH-003, ARCH-005)</li><li>[x] 8.3 Protocol validation and error contract (BUG-006, SEC-003, SEC-004, ARCH-006)</li><li>[x] 8.4 Bridge sessions, token, queue bound, batch semantics, events (SEC-001, BUG-002/003/004, ARCH-004)</li><li>[x] 8.5 WebView host: navigation policy, SDK in top frame, lifecycle (SEC-001, BUG-011)</li><li>[x] 8.6 Security components: sandbox path, permissions, rate limiter, guard, concurrency (SEC-002, SEC-005, SEC-008, CONC-001/002, BUG-012)</li><li>[x] 8.7 Cache LRU and mutation invalidation (BUG-001, PERF-001)</li><li>[x] 8.8 Plugin manager pipeline, capabilities and metrics (ARCH-002, STAT-001, SEC-003, BUG-007)</li><li>[x] 8.9 Plugins: storage, camera, geolocation (SEC-002, SEC-009, BUG-005/008/009/013, CONC-001)</li><li>[x] 8.10 Platform config: manifests, plist, Gradle signing and heap (SEC-006, BUG-010, PERF-002)</li><li>[x] 8.11 Tests: unit, integration, security, regression, perf smoke, JS SDK, E2E</li><li>[x] 8.12 CI workflow and coverage gate (CI-001, TEST-002, TEST-003)</li><li>[x] 8.13 Documentation (DOC-001..003, CI-002)</li></ul><h2 id="_9-test-plan" tabindex="-1">9. Test Plan <a class="header-anchor" href="#_9-test-plan" aria-label="Permalink to &quot;9. Test Plan&quot;">​</a></h2><p>See <code>docs/TESTING.md</code>. Summary:</p><ul><li>Unit: protocol, bridge, navigation policy, sandbox path, rate limiter, guard, permission manager, concurrency limiter, cache, registry, manager, plugins.</li><li>Integration: JS-shaped JSON → bridge → manager → plugin → response (<code>test/integration</code>).</li><li>Security: traversal, symlink escape, unauthorized token, malformed protocol, oversized message, unknown plugin/method, permission denial, rate abuse, concurrency abuse, error disclosure (<code>test/security</code>).</li><li>Regression: tests for the BUG/SEC/CONC findings in <code>test/regression</code>, plus regression-named tests in <code>test/unit</code> (see <code>docs/TESTING.md</code>).</li><li>JavaScript SDK: the injected SDK is executed in a Node VM (<code>test/js</code>).</li><li>E2E: Android emulator, real WebView (<code>integration_test</code>).</li></ul><h2 id="_10-security-plan" tabindex="-1">10. Security Plan <a class="header-anchor" href="#_10-security-plan" aria-label="Permalink to &quot;10. Security Plan&quot;">​</a></h2><p>Covered in <code>docs/SECURITY.md</code> (threat model, trust boundary, origin policy, permissions, storage, rate limiting, concurrency, error disclosure, known limitations).</p><h2 id="_11-performance-plan" tabindex="-1">11. Performance Plan <a class="header-anchor" href="#_11-performance-plan" aria-label="Permalink to &quot;11. Performance Plan&quot;">​</a></h2><ul><li>Cache LRU is O(1) (PERF-001).</li><li>Benchmark-style smoke tests in <code>test/performance</code> assert bounded time for bridge round trips, cache hit/miss and event throughput.</li><li>Message size limit bounds worst-case JSON parse cost (SEC-004).</li></ul><h2 id="_12-ci-cd-plan" tabindex="-1">12. CI/CD Plan <a class="header-anchor" href="#_12-ci-cd-plan" aria-label="Permalink to &quot;12. CI/CD Plan&quot;">​</a></h2><p><code>.github/workflows/ci.yml</code>, triggered on <code>push</code> to <code>main</code> and <code>arena/**</code>, on <code>pull_request</code>, and manually:</p><ol><li><code>analyze-and-test</code> — <code>flutter analyze --fatal-warnings</code>; <code>format_report.sh</code> (dart format check); <code>flutter test test/ --coverage</code>; coverage gate (55 %).</li><li><code>js-sdk-tests</code> — Node VM tests for the injected SDK.</li><li><code>android-build</code> — debug and release APK builds.</li><li><code>android-e2e</code> — emulator run of <code>integration_test</code>, through <code>run_e2e.sh</code>.</li><li><code>ios-build</code> — macOS build without codesign (CocoaPods; SPM disabled).</li></ol><p>Release signing is injected via environment variables only; no secret is stored in the repository.</p><h2 id="_13-documentation-plan" tabindex="-1">13. Documentation Plan <a class="header-anchor" href="#_13-documentation-plan" aria-label="Permalink to &quot;13. Documentation Plan&quot;">​</a></h2><p>README, docs/ARCHITECTURE.md, docs/SECURITY.md, docs/TESTING.md, this plan and the worklog. Each document is kept in line with the code in the same change.</p><h2 id="_14-acceptance-criteria" tabindex="-1">14. Acceptance Criteria <a class="header-anchor" href="#_14-acceptance-criteria" aria-label="Permalink to &quot;14. Acceptance Criteria&quot;">​</a></h2><ul><li>All P0/P1 findings are <code>[x]</code> with tests.</li><li><code>flutter analyze --fatal-warnings</code>, <code>flutter test</code>, Node SDK tests, Android debug and release builds, and the Android E2E pass in GitHub Actions on the pushed commit, including <code>dart format</code> and the 55 % coverage gate.</li><li>Docs describe the behaviour in the code.</li></ul><h2 id="_15-completion-status" tabindex="-1">15. Completion Status <a class="header-anchor" href="#_15-completion-status" aria-label="Permalink to &quot;15. Completion Status&quot;">​</a></h2><p>Work items are complete in code. Verification status is recorded in the worklog and in the final verification section below.</p><p>Blocked items: none. IOS-001 was blocked by the lack of a Flutter SDK and a macOS host in the sandbox. It is no longer blocked: the iOS job in CI builds the app on a macOS runner (see section 12). The remaining gap is that the app is not run on an iOS device or simulator, which is recorded in <code>docs/TESTING.md</code>.</p><h2 id="_16-final-verification" tabindex="-1">16. Final Verification <a class="header-anchor" href="#_16-final-verification" aria-label="Permalink to &quot;16. Final Verification&quot;">​</a></h2><p>Final verification pass 5 is recorded in <code>docs/WORKLOG.md</code>. This section is the summary.</p><p><strong>Final Status: COMPLETE</strong></p><h3 id="repository-state" tabindex="-1">Repository state <a class="header-anchor" href="#repository-state" aria-label="Permalink to &quot;Repository state&quot;">​</a></h3><ul><li>Branch <code>arena/a3bec261-sweet-melon</code>. Local HEAD equals <code>origin</code> HEAD at each push, and the working tree was clean after each push.</li><li>Production code, tests, Android and iOS configuration and CI workflow are unchanged since <code>8b1fa1a</code>. That commit&#39;s CI run 37835701145 was green. Later commits <code>5fe5557</code> and <code>bdb204c</code> change only <code>docs/</code>.</li><li>CI runs that are green on the exact commits: <code>37836821932</code> on <code>5fe5557</code>, and <code>37839069513</code> on <code>bdb204c</code>.</li></ul><h3 id="ci-run-37839069513-commit-bdb204c" tabindex="-1">CI (run 37839069513, commit <code>bdb204c</code>) <a class="header-anchor" href="#ci-run-37839069513-commit-bdb204c" aria-label="Permalink to &quot;CI (run 37839069513, commit \`bdb204c\`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Job</th><th>Result</th><th>Steps verified</th></tr></thead><tbody><tr><td>Injected JavaScript SDK (Node VM)</td><td>PASS</td><td><code>node --test test/js/bridge_sdk.test.mjs</code></td></tr><tr><td>Analyze, unit, security and regression tests</td><td>PASS</td><td>static analysis (<code>--fatal-warnings</code>), tests with coverage, coverage gate, format check, coverage upload</td></tr><tr><td>Android build (debug and release)</td><td>PASS</td><td>release is unsigned (no keystore in CI)</td></tr><tr><td>Android end-to-end (emulator)</td><td>PASS</td><td><code>run_e2e.sh</code> (exit code 0; two <code>E2E_OK</code> markers required by the script)</td></tr><tr><td>iOS build (macOS, no codesign)</td><td>PASS</td><td>CocoaPods install and <code>flutter build ios --debug --no-codesign</code></td></tr></tbody></table><p>Coverage: the gate passed at the enforced 55 % threshold. The exact measured percentage for the final commit was not recoverable from the available CI logs or artifacts in this pass (both downloads failed with EOF). The earlier 58.18 % belongs to <code>69b6d17</code> and is not the final value. The threshold was not lowered.</p><p>Local verification: only the JS SDK suite was run locally (Node 22.22.3, 16/16 pass). Dart and Flutter are not installed in this sandbox, so Dart format, analyze and tests are verified in CI only.</p><h3 id="requirement-evidence" tabindex="-1">Requirement evidence <a class="header-anchor" href="#requirement-evidence" aria-label="Permalink to &quot;Requirement evidence&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Requirement</th><th>Implementation</th><th>Test</th><th>Verification</th></tr></thead><tbody><tr><td>BUG-007</td><td>Sequential <code>stopOnError</code>: later requests are not dispatched; skipped requests get a result; parallel limitation documented</td><td><code>PluginManager.executeBatch</code> (sequential loop checks <code>settled</code> and <code>stopOnError</code>; skipped requests get <code>CANCELLED</code>)</td><td><code>test/regression/batch_stop_on_error_test.dart</code></td><td>Real manager path; passed in CI</td></tr><tr><td>BUG-008</td><td>Picker cancel: <code>ImagePicker</code> null → <code>PluginException(cancelled)</code> → <code>_fail</code> → <code>CANCELLED</code>, slot released, counted in <code>errorCount</code></td><td><code>CameraPlugin._takePhoto</code>; manager <code>on PluginException</code>; <code>ExecutionGuard</code> <code>finally</code></td><td><code>test/regression/camera_cancel_test.dart</code> (response code, repeated calls, stats)</td><td>Real engine path with a fake picker; passed in CI</td></tr><tr><td>BUG-011</td><td>Dispose detaches the executor and ends the session; late callbacks cannot change the live session</td><td><code>WebViewHost.dispose</code> → <code>BridgeAttachment.detach</code> → <code>MessageBridge.detachJsExecutor</code> and <code>endSession</code></td><td><code>test/regression/webview_lifecycle_test.dart</code> (real <code>MessageBridge</code>)</td><td>Passed in CI. The widget callbacks themselves are not driven by a test (see TESTING.md)</td></tr><tr><td>8.5</td><td>Navigation policy, SDK in top frame, lifecycle</td><td><code>NavigationPolicy</code> (wired in <code>WebViewHost</code>); SDK <code>window.top</code> guard; <code>BridgeAttachment</code></td><td><code>navigation_policy_test</code>, <code>bridge_sdk.test.mjs</code> (iframe refusal), <code>webview_lifecycle_test</code></td><td>Passed in CI and locally (JS)</td></tr><tr><td>8.9</td><td>Storage, camera, geolocation behaviour</td><td><code>SandboxPath</code>, storage size limits; camera cancel and validation; geolocation watches and timeout</td><td><code>storage_path_test</code>, <code>storage_security_test</code>, <code>camera_validation_test</code>, <code>camera_cancel_test</code>, <code>camera_concurrency_test</code> (CONC-001), <code>geolocation_lifecycle_test</code>, <code>argument_validation_test</code></td><td>Passed in CI</td></tr><tr><td>8.10</td><td>Manifests, Info.plist, Gradle signing and heap</td><td><code>AndroidManifest.xml</code> (CAMERA, FINE and COARSE location); iOS usage strings; <code>build.gradle.kts</code> signing from env; <code>gradle.properties</code> heap</td><td>Android and iOS CI build jobs</td><td>Passed in CI</td></tr><tr><td>8.11</td><td>Unit, integration, security, regression, performance smoke, JS SDK, E2E</td><td><code>test/unit</code>, <code>test/integration</code>, <code>test/security</code>, <code>test/regression</code>, <code>test/performance</code>, <code>test/js</code>, <code>integration_test</code></td><td>the Dart suite and JS suite, E2E job</td><td>Passed in CI</td></tr></tbody></table><h3 id="plan-status" tabindex="-1">Plan status <a class="header-anchor" href="#plan-status" aria-label="Permalink to &quot;Plan status&quot;">​</a></h3><ul><li>Every item is <code>[x]</code>. None is <code>[~]</code>, <code>[ ]</code>, <code>[!]</code> or <code>[-]</code>.</li><li>The <code>[-]</code> status is not used anywhere in this plan. Its meaning is written in the legend.</li><li>SM-001 to SM-012 are mapped in section 5a. Two of them (SM-007, SM-011) are covered at the Dart level only, as stated there.</li><li>No P0 or P1 item is open.</li></ul><h3 id="historical-e2e-incident" tabindex="-1">Historical E2E incident <a class="header-anchor" href="#historical-e2e-incident" aria-label="Permalink to &quot;Historical E2E incident&quot;">​</a></h3><p>Run 37815334536 (commit <code>1b00c87</code>) failed in the Android E2E job. The check-run annotations report <code>e2e.rc was not written</code>. The full logs could not be read. The root cause is not conclusively established, and this document does not call the failure a flake. The E2E harness was then rewritten (<code>cb938ff</code>): it writes <code>e2e.txt</code> first, and an EXIT trap writes <code>e2e.rc</code> on every path. Subsequent E2E runs passed: <code>37834548307</code>, <code>37835701145</code>, <code>37836821932</code> and <code>37839069513</code>.</p><h3 id="known-limits-documented-not-blockers" tabindex="-1">Known limits (documented, not blockers) <a class="header-anchor" href="#known-limits-documented-not-blockers" aria-label="Permalink to &quot;Known limits (documented, not blockers)&quot;">​</a></h3><ul><li>No automated test runs the page&#39;s JavaScript inside the real WebView. The Node VM tests cover the SDK code, and the device test covers boot and the storage path.</li><li>The iOS job builds the app without codesign. The app is not run on an iOS device or simulator.</li><li>The native geolocation subscription and the image picker are not exercised on a device. Their Dart-level logic is tested with fakes.</li><li>Parallel batches do not apply <code>stopOnError</code> (documented in <code>docs/SECURITY.md</code>).</li><li>The symlink tests are skipped on Windows only (<code>skip: Platform.isWindows</code>). CI runs on Linux.</li><li>The Android and iOS bundle identifiers are placeholders (<code>com.example.sweet_melon</code>). <code>README.md</code> says to change them before publishing.</li></ul>`,91)])])}const g=t(d,[["render",n]]);export{h as __pageData,g as default};
